import * as THREE from 'three';
if (typeof global.TextDecoder === 'undefined') {
  global.TextDecoder = class PolyfillTextDecoder {
    decode(bytes) {
      if (!bytes) return '';
      const u8 = bytes instanceof Uint8Array ? bytes : new Uint8Array(bytes.buffer || bytes, bytes.byteOffset || 0, bytes.byteLength || bytes.length || 0);
      let out = '';
      for (let i = 0; i < u8.length; i += 1) out += String.fromCharCode(u8[i]);
      try {
        return decodeURIComponent(escape(out));
      } catch {
        return out;
      }
    }
  };
}
import { Asset } from 'expo-asset';
import * as FileSystem from 'expo-file-system/legacy';
import { toByteArray } from 'base64-js';
