// Pre-rendered 2,541-triangle 3D 2x2_lego_brick.glb meshes (pitched 35° X, angled 45° Y, GGX PBR baseColorFactor)
export const LEGO_3D_GLB_RENDERS = Object.freeze(["data:image/png;base64,", "data:image/png;base64,", "data:image/png;base64,", "data:image/png;base64,", "data:image/png;base64,", "data:image/png;base64,", "data:image/png;base64,", "data:image/png;base64,"]);

// Module-level singleton cache so brain-atlas.glb and 2x2_lego_brick.glb
// are decoded once per app session and NEVER re-trigger 'offline asset loading'.
let cachedBrainBuffer = null;
let brainBufferPromise = null;
let cachedLegoBuffer = null;
let legoBufferPromise = null;

export async function preloadBrainBuffer() {
  if (cachedBrainBuffer) return cachedBrainBuffer;
  if (brainBufferPromise) return brainBufferPromise;
  brainBufferPromise = (async () => {
    const asset = Asset.fromModule(require('../../../assets/visuals/brain-atlas.glb'));
    await asset.downloadAsync();
    if (!asset.localUri) throw new Error('Offline model is unavailable');
    const encoded = await FileSystem.readAsStringAsync(asset.localUri, {
      encoding: FileSystem.EncodingType.Base64,
    });
    const bytes = toByteArray(encoded);
    cachedBrainBuffer = bytes.buffer.slice(bytes.byteOffset, bytes.byteOffset + bytes.byteLength);
    return cachedBrainBuffer;
  })().catch(err => {
    brainBufferPromise = null;
    throw err;
  });
  return brainBufferPromise;
}

export async function preloadLegoBuffer() {
  if (cachedLegoBuffer) return cachedLegoBuffer;
  if (legoBufferPromise) return legoBufferPromise;
  legoBufferPromise = (async () => {
    try {
      const asset = Asset.fromModule(require('../../../assets/visuals/2x2_lego_brick.glb'));
      await asset.downloadAsync();
      if (!asset.localUri) return null;
      const encoded = await FileSystem.readAsStringAsync(asset.localUri, {
        encoding: FileSystem.EncodingType.Base64,
      });
      const bytes = toByteArray(encoded);
      cachedLegoBuffer = bytes.buffer.slice(bytes.byteOffset, bytes.byteOffset + bytes.byteLength);
      getSharedLegoBrickLoader(cachedLegoBuffer);
      return cachedLegoBuffer;
    } catch {
      return null;
    }
  })();
  return legoBufferPromise;
}

/**
 * Null-safe WebGL info-log wrapper for Android expo-gl (OpenGL ES 3.2).
 * Prevents Three.js r162 onFirstUse() from crashing on .trim() when
 * gl.getProgramInfoLog / gl.getShaderInfoLog return null or undefined,
 * while preserving real driver log strings and keeping COMPILE_STATUS
 * and LINK_STATUS checks 100% active.
 */
export function patchGlContextForThree(gl) {
  if (!gl || gl.__myelinPatched) return gl;
  gl.__myelinPatched = true;
  const rawProgramLog = typeof gl.getProgramInfoLog === 'function' ? gl.getProgramInfoLog.bind(gl) : null;
  const rawShaderLog = typeof gl.getShaderInfoLog === 'function' ? gl.getShaderInfoLog.bind(gl) : null;
  const rawShaderSource = typeof gl.getShaderSource === 'function' ? gl.getShaderSource.bind(gl) : null;

  gl.getProgramInfoLog = program => {
    try {
      const res = rawProgramLog ? rawProgramLog(program) : '';
      return typeof res === 'string' ? res : '';
    } catch (err) {
      return `getProgramInfoLog error: ${String(err)}`;
    }
  };

  gl.getShaderInfoLog = shader => {
    try {
      const res = rawShaderLog ? rawShaderLog(shader) : '';
      return typeof res === 'string' ? res : '';
    } catch (err) {
      return `getShaderInfoLog error: ${String(err)}`;
    }
  };

  gl.getShaderSource = shader => {
    try {
      const res = rawShaderSource ? rawShaderSource(shader) : '';
      return typeof res === 'string' ? res : '';
    } catch {
      return '';
    }
  };

  return gl;
}

/**
 * Visually faithful static chalk-and-dusty-blue fallback rendered when WebGL
 * is initializing or unavailable on an Android device.
 */
export const StaticChalkVisualFallback = memo(function StaticChalkVisualFallback({
  progress = 0,
  model = 'bottle',
}) {
  const clamped = Math.max(0, Math.min(100, Number(progress) || 0));
  if (model === 'stopwatch') {
    return (
      <View
        accessible={false}
        pointerEvents="none"
        style={styles.fallbackWrap}>
        <Image
          source={{ uri: CHALK_BOTTLE_FALLBACK_TEXTURES.stopwatchBase }}
          style={styles.fallbackImage}
          resizeMode="contain"
        />
      </View>
    );
  }

  const fillFraction = clamped <= 0 ? 0 : clamped >= 100 ? 1 : 0.14 + (clamped / 100) * 0.72;
  const clipHeightPct = `${Math.round(fillFraction * 100)}%`;

  return (
    <View
      accessible={false}
      pointerEvents="none"
      style={styles.fallbackWrap}>
      <View style={styles.fallbackStageBox}>
        <Image
          source={{ uri: CHALK_BOTTLE_FALLBACK_TEXTURES.bottleEmpty }}
          style={styles.fallbackImage}
          resizeMode="contain"
        />
        {clamped > 0 ? (
          <View style={[styles.fallbackFillClip, { height: clipHeightPct }]}>
            <Image
              source={{ uri: CHALK_BOTTLE_FALLBACK_TEXTURES.bottleFull }}
              style={styles.fallbackImageBottomAnchored}
              resizeMode="contain"
            />
          </View>
        ) : null}
      </View>
    </View>
  );
});

export const NativeProgressVisual = memo(function NativeProgressVisual({
  progress = 0,
  model = 'bottle',
  paused = false,
  viewportHeight,
}) {
  const [error, setError] = useState(null);
  const [ready, setReady] = useState(false);
  const [contextKey, setContextKey] = useState(0);
  const latest = useRef(progress);
  const modelRef = useRef(model);
  const engineRef = useRef(null);
  const pausedRef = useRef(paused);
  const live = useRef(true);
  const active = useRef(true);
  const focused = useRef(true);
  const focusSettled = useRef(true);
  const reduced = useRef(false);
  const syncLoop = useRef(() => {});
  useEffect(() => { syncLoop.current(); }, [paused]);
  const cleanup = useRef(() => {});
  const drag = useRef({ x: 0, y: 0 });
  const start = useRef({ x: 0, y: 0 });
  const contextCount = useRef(0);
  const hasCurrentContext = useRef(false);
  const surfaceLayout = useRef({ width: 0, height: 0 });
  const startupAttempts = useRef(0);

  useEffect(() => {
    if (ready || error || paused) return;
    let timer;
    const checkStartup = () => {
      if (!live.current) return;
      const action = startupRecoveryAction({
        active: active.current,
        focused: focused.current,
        paused: pausedRef.current,
        attempts: startupAttempts.current,
      });
      if (action === 'wait') {
        timer = setTimeout(checkStartup, 8000);
      } else if (action === 'retry') {
        startupAttempts.current += 1;
        hasCurrentContext.current = false;
        cleanup.current();
        setContextKey(key => key + 1);
      } else {
        cleanup.current();
        const { width, height } = surfaceLayout.current;
        const stage = hasCurrentContext.current ? 'A graphics context was created, but no frame was drawn.' : `Android did not create a graphics context (view ${Math.round(width)} × ${Math.round(height)}).`;
        setError(`${stage} Tap retry to try again.`);
      }
    };
    timer = setTimeout(checkStartup, 8000);
    return () => clearTimeout(timer);
  }, [ready, error, paused, contextKey]);

  latest.current = Math.max(0, Math.min(100, Number(progress) || 0));
  modelRef.current = model || 'bottle';
  pausedRef.current = Boolean(paused);

  useEffect(() => {
    if (engineRef.current && typeof engineRef.current.setModel === 'function') {
      engineRef.current.setModel(model || 'bottle');
    }
  }, [model]);

  useFocusEffect(
    useCallback(() => {
      focused.current = true;
      if (__DEV__) console.info('[Myelin 3D] focus', { contexts: contextCount.current });
      // Resume the existing graphics context; retry remains available if the
      // operating system has discarded it while the app was away.
      focusSettled.current = !engineRef.current;
      const transitionTimer = setTimeout(() => {
        focusSettled.current = true;
        syncLoop.current();
      }, 220);
      syncLoop.current();
      return () => {
        clearTimeout(transitionTimer);
        focused.current = false;
        if (__DEV__) console.info('[Myelin 3D] blur');
        focusSettled.current = false;
        syncLoop.current();
      };
    }, []),
  );

  useEffect(() => {
    live.current = true;
    if (__DEV__) console.info('[Myelin 3D] mount');
    active.current = AppState.currentState !== 'background' && AppState.currentState !== 'inactive';
    const sub = AppState.addEventListener('change', s => {
      active.current = s === 'active';
      syncLoop.current();
    });
    AccessibilityInfo.isReduceMotionEnabled().then(v => {
      reduced.current = v;
    });
    const motion = AccessibilityInfo.addEventListener('reduceMotionChanged', v => {
      reduced.current = v;
    });
    return () => {
      live.current = false;
      if (__DEV__) console.info('[Myelin 3D] unmount');
      sub.remove();
      motion.remove();
      cleanup.current();
    };
  }, []);

  const pan = useRef(
    PanResponder.create({
      onStartShouldSetPanResponder: () => false,
      onMoveShouldSetPanResponder: (_, g) =>
        Math.abs(g.dx) > 8 && Math.abs(g.dx) > Math.abs(g.dy),
      onPanResponderGrant: () => {
        start.current = { ...drag.current };
      },
      onPanResponderMove: (_, g) => {
        drag.current = {
          x: start.current.x + g.dx * 0.007,
          y: Math.max(-0.5, Math.min(0.5, start.current.y + g.dy * 0.006)),
        };
      },
    }),
  ).current;

  const onContextCreate = useCallback(async gl => {
    // Android can replace the native surface without unmounting this component.
    // Dispose the old renderer before accepting the new GL context.
    cleanup.current();
    setReady(false);
    setError(null);
    contextCount.current += 1;
    hasCurrentContext.current = true;
    const contextStart = Date.now();
    if (__DEV__) console.info('[Myelin 3D] context created', { count: contextCount.current });


    let engine;
    let renderer;
    let frame = 0;
    let disposed = false;
    let stage = 'context inspection';
    let details = '';

    const report = e => {
      const message = `${stage}: ${String(e)}\n${details}\n${e?.stack || ''}`;
      console.error('MYELIN_NATIVE_VISUAL', message);
      if (live.current) setError(message);
    };

    const dispose = () => {
      disposed = true;
      engineRef.current = null;
      cancelAnimationFrame(frame);
      engine?.dispose();
      renderer?.dispose();
    };

    cleanup.current = dispose;

    try {
      patchGlContextForThree(gl);
      const version = gl.getParameter(gl.VERSION);
      const rawVersion = gl.getParameter(0x1f02);
      const units = gl.getParameter(gl.MAX_COMBINED_TEXTURE_IMAGE_UNITS);
      details = `context=${gl.contextId}; size=${gl.drawingBufferWidth}x${gl.drawingBufferHeight}; VERSION=${gl.VERSION}; version=${String(version)}; rawVersion=${String(rawVersion)}; textureUnits=${String(units)}; class=${gl.constructor?.name}; three=${THREE.REVISION}`;
      if (typeof version !== 'string' || !Number.isFinite(units) || units < 1) {
        throw new Error('Native graphics context returned invalid capabilities');
      }

      const legoBuffer = cachedLegoBuffer;
      if (disposed || !live.current) return;

      stage = 'object construction';
      engine = createNativeScene(
        null,
        message => report(new Error(message)),
        legoBuffer,
        { mode: modelRef.current },
      );
      engineRef.current = engine;

      const canvas = {
        width: gl.drawingBufferWidth,
        height: gl.drawingBufferHeight,
        style: {},
        addEventListener() {},
        removeEventListener() {},
        clientHeight: gl.drawingBufferHeight,
      };

      stage = 'renderer initialization';
      renderer = new THREE.WebGLRenderer({
        canvas,
        context: gl,
        antialias: false,
        alpha: true,
      });
      // Keep shader compilation and link checking enabled so real GLSL failures are caught
      if (renderer.debug) {
        renderer.debug.checkShaderErrors = true;
        renderer.debug.onShaderError = (glCtx, program, glVertexShader, glFragmentShader) => {
          const vsLog = glCtx.getShaderInfoLog(glVertexShader);
          const fsLog = glCtx.getShaderInfoLog(glFragmentShader);
          const progLog = glCtx.getProgramInfoLog(program);
          report(
            new Error(
              `GLSL shader error: program="${String(progLog || '').trim()}" vertex="${String(vsLog || '').trim()}" fragment="${String(fsLog || '').trim()}"`,
            ),
          );
        };
      }
      renderer.setSize(gl.drawingBufferWidth, gl.drawingBufferHeight);
      renderer.setClearColor(CHALK_STAGE_RGB, 1);
      engine.camera.aspect = gl.drawingBufferWidth / gl.drawingBufferHeight;
      engine.camera.updateProjectionMatrix();

      let last = 0;
      let firstFrame = true;
      let sampledFrames = 0, slowFrames = 0, slowestFrameMs = 0;
      function sync() {
        if (disposed || !active.current || !focused.current || !focusSettled.current || pausedRef.current) {
          cancelAnimationFrame(frame);
          frame = 0;
          last = 0;
        } else if (!frame) {
          frame = requestAnimationFrame(tick);
        }
      }
      function tick(now) {
        frame = 0;
        if (disposed || !active.current || !focused.current || !focusSettled.current || pausedRef.current) return;
        // Avoid competing with navigation and touch handling at a full display refresh rate.
        if (last && now - last < 30) { sync(); return; }
        try {
          const frameStart = __DEV__ ? Date.now() : 0;
          const dt = last ? Math.min(64, now - last) : 16;
          last = now;
          engine.update(dt, latest.current, reduced.current, drag.current);
          stage = 'frame rendering';
          renderer.render(engine.scene, engine.camera);
          gl.endFrameEXP();
          if (__DEV__) {
            const frameMs = Date.now() - frameStart;
            sampledFrames += 1;
            if (frameMs > 16) slowFrames += 1;
            slowestFrameMs = Math.max(slowestFrameMs, frameMs);
            if (sampledFrames === 120) {
              console.info('[Myelin 3D] JS frame work', { slowFrames, slowestFrameMs, drawCalls: renderer.info.render.calls, points: renderer.info.render.points });
              sampledFrames = 0; slowFrames = 0; slowestFrameMs = 0;
            }
          }
          if (firstFrame && live.current) {
            firstFrame = false;
            startupAttempts.current = 0;
            if (__DEV__) console.info('[Myelin 3D] first frame', { ms: Date.now() - contextStart });
            setReady(true);
          }
          sync();
        } catch (e) {
          report(e);
          dispose();
        }
      }

      syncLoop.current = sync;
      sync();
    } catch (e) {
      report(e);
      dispose();
    }
  }, []);

  return (
    <View style={styles.stageContainer} {...pan.panHandlers}>
      <GLView key={contextKey} style={[styles.glView, { height: viewportHeight }]} collapsable={false} onLayout={event => { surfaceLayout.current = event.nativeEvent.layout; }} onContextCreate={onContextCreate} />
      {!ready ? <StaticChalkVisualFallback progress={progress} model={model} /> : null}
      {error ? <Pressable accessibilityRole="button" accessibilityLabel="Retry native 3D visual" onPress={() => {
        startupAttempts.current = 0; hasCurrentContext.current = false; cleanup.current(); setReady(false); setError(null); setContextKey(key => key + 1);
      }} style={{ position: 'absolute', top: 8, alignSelf: 'center', padding: 12, backgroundColor: '#252520' }}>
        <Text style={{ color: '#F2E7D0' }}>3D unavailable · Tap to retry</Text>
      </Pressable> : null}
      {error ? (
        <ScrollView style={styles.diagnosticOverlay}>
          <Text
            selectable
            accessibilityLiveRegion="polite"
            style={styles.diagnosticText}>
            {'Visual diagnostic: ' + error}
          </Text>
        </ScrollView>
      ) : null}
    </View>
  );
});

export { getBottleMeniscusNormalizedY };

export const NativeLegoIcon = memo(function NativeLegoIcon({
  colorIndex = 0,
  size = 38,
  style,
}) {
  const floatProgress = useSharedValue(0);

  useEffect(() => {
    preloadLegoBuffer().catch(() => {});
    const staggerMs = (Math.abs(Math.round(colorIndex) || 0) % 6) * 210;
    floatProgress.value = withDelay(
      staggerMs,
      withRepeat(
        withSequence(
          withTiming(1, { duration: 1550, easing: Easing.inOut(Easing.sin) }),
          withTiming(0, { duration: 1550, easing: Easing.inOut(Easing.sin) }),
        ),
        -1,
        true,
      ),
    );
  }, [colorIndex, floatProgress]);

  const floatingBrickStyle = useAnimatedStyle(() => {
    const translateY = interpolate(floatProgress.value, [0, 1], [2.4, -3.8]);
    const rotateZ = interpolate(floatProgress.value, [0, 1], [-2.5, 2.5]);
    const scale = interpolate(floatProgress.value, [0, 1], [0.97, 1.04]);
    return {
      transform: [
        { translateY },
        { rotateZ: `${rotateZ}deg` },
        { scale },
      ],
    };
  });

  const floatingShadowStyle = useAnimatedStyle(() => {
    const scaleX = interpolate(floatProgress.value, [0, 1], [1.05, 0.72]);
    const opacity = interpolate(floatProgress.value, [0, 1], [0.26, 0.10]);
    return {
      opacity,
      transform: [{ scaleX }, { scaleY: 0.42 }],
    };
  });

  const resolvedIndex = Math.abs(Math.round(colorIndex) || 0) % LEGO_3D_GLB_RENDERS.length;
  const uri = LEGO_3D_GLB_RENDERS[resolvedIndex];

  return (
    <View
      accessibilityElementsHidden
      importantForAccessibility="no-hide-descendants"
      style={[
        styles.legoContainer,
        { width: size, height: size },
        style,
      ]}>
      <Animated.View
        pointerEvents="none"
        style={[
          styles.floatingShadow,
          {
            width: size * 0.58,
            height: size * 0.28,
            bottom: 1,
            borderRadius: size * 0.25,
          },
          floatingShadowStyle,
        ]}
      />
      <Animated.View style={[styles.brickImageWrap, floatingBrickStyle]}>
        <Image
          source={{ uri }}
          style={{ width: size * 0.92, height: size * 0.92 }}
          resizeMode="contain"
        />
      </Animated.View>
    </View>
  );
});

